def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    for color in set(counts) - {bg}:
        for slope in (1, -1):
            lines = defaultdict(list)
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == color:
                        key = c-r if slope == 1 else c+r
                        lines[key].append((r,c))
            for key, pts in lines.items():
                if len(pts) < 2:
                    continue
                for r in range(h):
                    c = r+key if slope == 1 else key-r
                    if 0 <= c < w and out[r][c] == bg:
                        out[r][c] = color
    return out
